function split(total, people, tipPct, taxPct){
  total=+total; people=+people; tipPct=+tipPct||0; taxPct=+taxPct||0;
  if(!(total>=0) || !(people>0)) return {error:'金额须非负、人数须为正'};
  var tip=total*tipPct/100, tax=total*taxPct/100, grand=total+tip+tax;
  return {tip:tip, tax:tax, grand:grand, per:grand/people, perTip:tip/people, perTax:tax/people};
}
var EXPORTS={split:split};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.BillSplitForgePure = EXPORTS; }
